<?php declare(strict_types=1);$money=static fn(float$value):string=>'R$ '.number_format($value,2,',','.'); ?><div class="actions"><div><span class="status">ADM · Cursos</span><h1>Cursos e preços</h1><p class="meta">Configure valores e limites de parcelamento dos cursos sincronizados.</p></div><a class="button-primary" href="<?= $escape($basePath) ?>/admin/finance/products/create"><i class="fa-solid fa-plus"></i> Novo curso</a></div><?php if($message):?><p class="alert alert-success"><?= $escape($message) ?></p><?php endif;?><?php if($error):?><p class="alert alert-danger"><?= $escape($error) ?></p><?php endif;?><div class="table-responsive"><table><thead><tr><th>Curso</th><th>Unidade</th><th>Valor total</th><th>Parcelas</th><th>Formas</th><th>Situação</th><th>Ação</th></tr></thead><tbody><?php if($products===[]):?><tr><td colspan="7">Nenhum curso configurado.</td></tr><?php endif;?><?php foreach($products as$product):?><tr><td><strong><?= $escape($product['name']) ?></strong></td><td><?= $escape($product['unit_name']?:'Todas as unidades') ?></td><td><strong><?= $escape($money((float)$product['value'])) ?></strong></td><td>Até <?= (int)$product['max_installments'] ?>x</td><td><?= str_contains((string)$product['billing_types'],'PIX')?'Pix':'' ?><?= str_contains((string)$product['billing_types'],'CREDIT_CARD')?(str_contains((string)$product['billing_types'],'PIX')?' + ':'').'Cartão':'' ?></td><td><?= (int)$product['is_active']===1?'Ativo':'Inativo' ?></td><td><a class="button-icon" title="Editar curso" href="<?= $escape($basePath) ?>/admin/finance/products/<?= (int)$product['id'] ?>/edit"><i class="fa-solid fa-pen"></i></a></td></tr><?php endforeach;?></tbody></table></div>
